	lea	$FFFF4400, a0
	move.l	d0, d4
	move.w	d7, d6
loc_4C2:
	movem.l	d0-a3, -(sp)
	bsr.w	VDPDisableVInterrupt
	movem.l	(sp)+, d0-a3
	bsr.w	loc_4EC
	movem.l	d0-a3, -(sp)
	bsr.w	VDPEnableVInterrupt
	movem.l	(sp)+, d0-a3
	addi.w	#$20, d4
	adda.w	#$20, a0
	dbf	d6, loc_4C2
