loc_4EC:
	moveq	#0, d1
	move.l	#$F0F000, d2
	move.b	(a1), d1
	lsr.w	#1, d1
	bcc.s	loc_500
	move.l	#$F0F00, d2
loc_500:
	bclr	#0, d1
	beq.s	loc_508
	swap	d2
loc_508:
	movea.l	a0, a4
	adda.w	d1, a4
	move.l	d4, d3
	add.w	d1, d3
	move.w	(a4), d1
	and.w	d2, d1
	andi.w	#$3FFF, d3
	swap	d3
	move.l	d3, (a2)
	swap	d3
	move.w	(a3), d2
	ori.w	#$4000, d3
	swap	d3
	move.l	d3, (a2)
	swap	d3
	or.w	d1, d2
	move.w	d2, (a3)
	rts

