ConvertLegendToNeiWpns:
	lea	(char_inventory).w, a0
	lea	(LegendToNeiWpnData).l, a1
	move.w	#$80, d7
loc_EDE:
	lea	(a0,d7.w), a2
	move.w	(a2), d6
	; There's no check if the character's item number is 0. d6 which now holds the number of items will be subtracted and repeat the step right below because it needs to
	; loop through every item. If it's 0, it will subtract 2 and it will result in a negative number and it will loop many items and overwrite some other RAM addresses.
	; This bug is known as the Pron Glitch.
	; Add a test for 0 right here and branch to the part that subtracts $20 to d7 so that it processes the next character's items.
loc_EE4:
	move.w	(a2,d6.w), d0
	move.w	d0, d1
	andi.w	#$FF0, d0
	andi.w	#$F00F, d1
	lea	(a1), a3
	moveq	#(LegendToNeiWpnData_End-LegendToNeiWpnData)/4-1, d4
loc_EF6:
	cmp.w	(a3), d0
	bne.s	loc_F08
	bsr.w	loc_F1A
	move.w	$2(a3), d0
	move.w	d0, (a2,d6.w)
	bra.s	loc_F0E
loc_F08:
	addq.w	#4, a3
	dbf	d4, loc_EF6
loc_F0E:
	subq.w	#2, d6
	bne.s	loc_EE4
	subi.w	#$20, d7
	bcc.s	loc_EDE
	rts

loc_F1A:
	tst.w	d1		; is the item equipped?
	bpl.s	+		; if not, return
	movem.l	d0/a2-a3, -(sp)
	lea	(InventoryData).l, a3
	lea	(char_stats).w, a2
	adda.w	d0, a3
	move.w	d7, d0
	add.w	d0, d0
	add.w	d0, d0
	adda.w	d0, a2
	moveq	#0, d0
	move.b	$8(a3), d0
	sub.w	d0, $36(a2)
	sub.w	d0, $5C(a2)
	moveq	#0, d0
	move.b	$9(a3), d0
	sub.w	d0, $38(a2)
	sub.w	d0, $5E(a2)
	move.b	$A(a3), d0
	sub.b	d0, $24(a2)
	movem.l	(sp)+, d0/a2-a3
+
	rts

