	beq.s	loc_3322
	move.w	d1, d2
	subi.w	#ItemID_Sapphire, d1	; range from Sapphire
	subi.w	#ItemID_AquaParts, d2	; to Aqua Parts (not included)
	eor.w	d2, d1		; eor the two registers
