VDPEnableVInterrupt:
	move.w	(vdp_reg1_values).w, d0	; get 2nd VDP register values
	bset	#5, d0					; set the 6th bit (V Interrupt)
	move.w	d0, (vdp_reg1_values).w	; update values
	move.w	d0, vdp_control_port	; set register in VDP
	move	#$2000, sr				; enable all interrupts
	rts

VDPDisableVInterrupt:
	move	#$2700, sr				; disable all interrupts
	move.w	(vdp_reg1_values).w, d0	; get 2nd VDP register values
	bclr	#5, d0					; clear the 6th bit (V Interrupt)
	move.w	d0, (vdp_reg1_values).w	; update values
	move.w	d0, vdp_control_port	; set register in VDP
	rts

WaitVBlankAndGamePause:
	btst	#7, $FFFFD004.w
	beq.s	WaitVBlankAndGamePause		; wait until V blanking is over
	bclr	#7, $FFFFD004.w	; clear bit so that it will wait for the V blanking again
	move.b	$FFFFD004.w, d2
	btst	#6, d2
	beq.s	BranchTo_GenerateRandomNumber
	btst	#5, $FFFFD007.w
	bne.s	BranchTo_GenerateRandomNumber
	move.b	(joypad_pressed).w, d1
	btst	#ButtonStart, d1	; did we press the start button?
	beq.s	loc_6D84			; if not, branch
	moveq	#1, d0		; stop music
	bchg	#4, d2		; toggle paused bit
	beq.s	loc_6D7A	; branch if game was not paused
	move.b	#$80, d0	; if we pressed the start button when game was paused, resume music
loc_6D7A:
	jsr	(ResumeOrStopMusic).l
	move.b	d2, $FFFFD004.w ; update paused bit
loc_6D84:
	btst	#4, d2			; is game paused?
	beq.s	BranchTo_GenerateRandomNumber	; if not, branch
	bra.s	WaitVBlankAndGamePause		; we paused the game, so loop
	
