; These are generally the main character sprites on the level/map screen
; Each of these objects occupy 128 bytes in RAM
ProcessPrimaryObjs:
	btst	#6, $FFFFD007.w
	bne.s	+
	lea	(primary_obj_table).w, a5
	bsr.w	ProcessObject
	clr.b	(object_counter).w
loc_6DB0:
	moveq	#0, d0
	move.b	(object_counter).w, d0
	cmpi.b	#$A, d0		; did we process 5 objects?
	bcc.s	+			; if so, return
	addq.b	#2, (object_counter).w
	lea	(primary_obj_size).w, a0
	lea	(primary_obj_table).w, a5
	adda.w	(a0,d0.w), a5
	bsr.w	ProcessObject
	bra.s	loc_6DB0
ProcessObject:
	tst.b	(a5)
	bpl.s	+			; if slot is free, return
	movea.l	$4(a5), a0	; otherwise process object
	jsr	(a0)
+
	rts
	

