ReadJoypads:
	jsr	(StopZ80).l
	lea	hw_port_1_data, a0
	lea	(joypad_held).w, a1
	bsr.s	ReadJoypad		; read first joypad
	addq.w	#2, a0
	bsr.s	ReadJoypad		; read second joypad
	jmp	(StartZ80).l
	
ReadJoypad:
	move.b	#0, (a0)	; read joypad data port
	nop					; bus synchronization
	nop
	move.b	(a0), d1	; get joypad data - Start/A
	lsl.w	#2, d1		; shift them so they are at the 2 highest bits
	move.b	#$40, (a0)	; read joypad data port again
	nop					; bus synchronization
	nop
	move.b	(a0), d0	; get joypad data - C/B/Dpad
	andi.b	#$3F, d0	; C/B/Dpad in low 6 bits
	andi.b	#$C0, d1	; Start/A in high 2 bits
	or.b	d1, d0		; merge values from both registers
	not.b	d0			; revert bits so that '0' means not pressed, and '1' pressed; the hardware has this data with bit '0' meaning pressed, and '1' not pressed
	move.b	(a1), d1	; get previous joypad state
	eor.b	d0, d1		; toggle off buttons that are being held (for the pressed functionality)
	move.b	d0, (a1)+	; 'joypad held' functionality 
	and.b	d0, d1
	move.b	d1, (a1)+	; 'joypad pressed' functionality--input is only valid once and you need to release and press a button again to make it work
	rts

InitJoypads:
	jsr	(StopZ80).l
	moveq	#$40, d0
	lea	hw_port_1_control, a0
	move.b	d0, (a0)
	move.b	d0, $2(a0)
	jsr	(StartZ80).l
	rts

