MenuItem_ActionUse:
	bsr.w	Menu_GetItem
	move.w	d0, d7
	moveq	#0, d0
	move.b	$B(a3), d0	; get technique ID
	bmi.s	loc_8BDA	; if sign bit is set, branch (special action)
	tst.b	$C(a3)		; is technique effectiveness 0?
	beq.s	MenuItem_NoUse	; if so, branch
	cmpi.b	#ItemID_ShortSwd, d7
	bcc.s	MenuItem_NoUse	; don't do anything if item in the list is equal or greater than Short Sword
	cmpi.b	#TechID_Ner, d0	; are we past the healing techniques?
	bcc.s	MenuItem_NoUse	; if so, branch
	subi.b	#TechID_Res, d0		; are we before the healing techniques?
	bcs.s	MenuItem_NoUse	; if so, branch
	add.w	d0, d0		; multiply ID by 2 to get size of pointer
	addi.w	#$34, d0	
	move.w	d0, $2(a6)
	rts
