; ==========================================================
; Nemesis decompression
NemDecom:
	movem.l	d0-a3/a5, -(sp)
	lea	Nem_WriteRowToRAM(pc), a3
	lea	(nem_code_table).w, a1
	move.w	(a0)+, d2		; get number of patterns
	add.w	d2, d2
	bcc.s	+			; branch if the sign bit is not set
	lea	Nem_WriteRowToRAM_XOR-Nem_WriteRowToRAM(a3), a3	; otherwise use XOR mode
+
	add.w	d2, d2
	add.w	d2, d2		; number of 8-pixel rows in the uncompressed data
	movea.w	d2, a5
	moveq	#8, d3	; 8 pixels in a pattern row
	moveq	#0, d2
	moveq	#0, d4
	jsr	Nem_BuildCodeTable(pc)
	move.b	(a0)+, d5	; get first byte of compressed data
	asl.w	#8, d5		; shift to higher byte
	move.b	(a0)+, d5	; get second byte of compressed data
	moveq	#$10, d6	; set initial shift value
	bsr.w	Nem_ProcessCompressedData
	movem.l	(sp)+, d0-a3/a5
	rts

Nem_ProcessCompressedData:
	move.w	d6, d7
	subq.w	#8, d7		; get shift value
	move.w	d5, d1
	lsr.w	d7, d1		; shift so that high bit of the code is in bit position 7
	cmpi.b	#$FC, d1	; are the high 6 bits set?
	bcc.s	Nem_InlineData	; if so, it means inline data
	andi.w	#$FF, d1
	add.w	d1, d1
	move.b	(a1,d1.w), d0		; get the length of the code in bits
	ext.w	d0
	sub.w	d0, d6				; subtract from shift value so that the next code is read next time around
	cmpi.w	#9, d6				; does a new byte need to be read?
	bcc.s	+			; if not, branch
	addq.w	#8, d6
	asl.w	#8, d5
	move.b	(a0)+, d5	; read next byte
+
	move.b	$1(a1,d1.w), d1
	move.w	d1, d0
	andi.w	#$F, d1		; get palette index for pixel
	andi.w	#$F0, d0

Nem_GetRepeatCount:
	lsr.w	#4, d0		; get repeat count

Nem_WritePixel:
	lsl.l	#4, d4		; shift up by a nybble
	or.b	d1, d4		; write pixel
	subq.w	#1, d3		; has an entire 8-pixel row been written?
	bne.s	Nem_WritePixel_Loop	; if not, loop
	jmp	(a3)			; otherwise, write the row to its destination

NemDec_WriteIter:
	moveq	#0, d4		; reset row
	moveq	#8, d3		; reset nybble counter
Nem_WritePixel_Loop:
	dbf	d0, Nem_WritePixel
	bra.s	Nem_ProcessCompressedData
	

Nem_InlineData:
	subq.w	#6, d6		; 6 bits needed to signal inline data
	cmpi.w	#9, d6
	bcc.s	+
	addq.w	#8, d6
	asl.w	#8, d5
	move.b	(a0)+, d5
+
	subq.w	#7, d6		; and 7 bits needed for the inline data itself
	move.w	d5, d1
	lsr.w	d6, d1		; shift so that low bit of the code is in bit position 0
	move.w	d1, d0
	andi.w	#$F, d1		; get palette index for pixel
	andi.w	#$70, d0	; high nybble is repeat count for pixel
	cmpi.w	#9, d6
	bcc.s	Nem_GetRepeatCount
	addq.w	#8, d6
	asl.w	#8, d5
	move.b	(a0)+, d5
	bra.s	Nem_GetRepeatCount
	
; =========================================
; unused
;Nem_WriteRowToVDP:
	move.l	d4, (a4)
	subq.w	#1, a5
	move.w	a5, d4
	bne.s	NemDec_WriteIter
	rts
	
;Nem_WriteRowToVDP_XOR:
	eor.l	d4, d2
	move.l	d2, (a4)
	subq.w	#1, a5
	move.w	a5, d4
	bne.s	NemDec_WriteIter
	rts
; =========================================

Nem_WriteRowToRAM:
	move.l	d4, (a4)+
	subq.w	#1, a5
	move.w	a5, d4
	bne.s	NemDec_WriteIter
	rts

Nem_WriteRowToRAM_XOR:
	eor.l	d4, d2
	move.l	d2, (a4)+
	subq.w	#1, a5
	move.w	a5, d4
	bne.s	NemDec_WriteIter
	rts

Nem_BuildCodeTable:
	move.b	(a0)+, d0	; read first byte
loc_DA44:
	cmpi.b	#$FF, d0	; has the end of the code table description reached?
	bne.s	Nem_NewPalIndex	; if not, continue
	rts

Nem_NewPalIndex:
	move.w	d0, d7

loc_DA4E:
	move.b	(a0)+, d0	; read next byte
	bmi.s	loc_DA44	; if sign bit is set, process new palette index
	move.b	d0, d1
	andi.w	#$F, d7		; get palette index
	andi.w	#$70, d1	; get repeat count for palette index
	or.w	d1, d7		; merge palette index with repeat count
	andi.w	#$F, d0		; get the length of the code in bits
	move.b	d0, d1
	lsl.w	#8, d1
	or.w	d1, d7
	moveq	#8, d1
	sub.w	d0, d1		; is the code 8 bits long?
	bne.s	loc_DA78	; if not, do more processing
	move.b	(a0)+, d0	; get code
	add.w	d0, d0		; each code gets a word-sized entry in the table
	move.w	d7, (a1,d0.w)	; store the entry for the code
	bra.s	loc_DA4E		; repeat

loc_DA78:
	move.b	(a0)+, d0	; get code
	lsl.w	d1, d0		; shift so that high bit is in bit position 7
	add.w	d0, d0		; get index into code table
	moveq	#1, d5
	lsl.w	d1, d5
	subq.w	#1, d5
-
	move.w	d7, (a1,d0.w)	; store entry
	addq.w	#2, d0			; increment index
	dbf	d5, -
	bra.s	loc_DA4E
; ==========================================================

