; This routine determines whether it's a preemptive strike (characters/enemies) or not
Battle_SetAttackPriority:
	btst	#0, $FFFFD00A.w
	bne.s	Battle_SetupRegular
	btst	#1, $FFFFD008.w
	bne.s	Battle_SetupRegular
	bclr	#7, $FFFFD009.w
	bsr.w	GenerateRandomNumber	; get random number and store it into d0
	andi.b	#7, d0				; 0-7 (8 values)
	subq.b	#1, d0				; subtract 1
	bmi.s	Battle_SetupPreempStrike		; if number is negative, you surprised the monster
	beq.s	Battle_SetupAmbush			; if 0, you've been ambushed

Battle_SetupRegular:
	clr.w	$FFFFD084.w
	clr.w	$FFFFD082.w
	clr.w	$FFFFD09C.w
	clr.w	$FFFFD0A4.w
	st	$69(a6)
	bset	#4, $FFFFD00A.w
	bset	#6, $FFFFD00A.w
	bset	#5, $FFFFD00A.w
	move.w	#$1C, (game_general_routine).w
	rts

Battle_SetupPreempStrike:
	clr.w	$FFFFD084.w
	clr.w	$FFFFD082.w
	clr.w	$FFFFD09C.w
	clr.w	$FFFFD0A4.w
	bset	#6, $FFFFD00A.w
	bset	#5, $FFFFD00A.w
	bset	#7, $FFFFD009.w
	addq.w	#8, (game_general_routine).w
	rts

Battle_SetupAmbush:
	clr.w	$FFFFD084.w
	clr.w	$FFFFD082.w
	clr.w	$FFFFD09C.w
	clr.w	$FFFFD0A4.w
	st	$69(a6)
	bset	#4, $FFFFD00A.w
	addq.w	#4, (game_general_routine).w
	rts

