	lea	(loc_3D90A).l, a0
	tst.w	(party_members_num).w
	bne.s	+
	lea	(loc_3D90A).l, a0		; this is the same message as above, so this instruction and the check above are useless.
+
	lea	$FFFF2C0A, a1
	move.l	#$FFFFC0A7, (char_name_saved).w
	bsr.w	loc_FF0A
