Battle_PickMainCommands:
	btst	#1, $FFFFD00A.w	; is auto-battle disabled?
	beq.s	loc_E08E		; if so, branch
	moveq	#0, d0
	move.b	d0, $C(a6)
	bra.s	loc_E0A6		; 
loc_E08E:
	move.b	(joypad_pressed).w, d7
	beq.s	loc_E112		; if we didn't press any buttons, skip
	btst	#Button_C, d7	; did we press C?
	beq.s	loc_E0B2		; if not, branch
	jsr	(GetSelectionSound).l
	moveq	#0, d0
	move.b	$C(a6), d0	; get command index
