	bne.s	loc_E0C8
	move.w	#$20, (game_general_routine).w
	rts
	
; Now process directional buttons
; the index for the commands is as follows (in bits):
;
; bit 0 = cleared when on the top row of the grid; set when on the bottom row
; bit 1 = cleared when on the left column of the grid; set when on the right column

loc_E0C8:
	move.b	$C(a6), d6	; get command index
	move.b	d6, d2	; save it
	move.b	d7, d1	; save joypad input
	and.b	d2, d1	; only set d1 if we're on the bottom row
	btst	#ButtonUp, d1
	beq.s	loc_E0DE		; if we didn't press up or we are on the top row, branch
	bclr	#0, d6			; set top row
	bra.s	loc_E126
loc_E0DE:
	add.b	d2, d2		; shift command bit by 1 (because the down button is in bit 1 on the joypad memory location
	not.b	d2			; reverse to check what row we're on
	move.b	d7, d1		; save joypad input
	and.b	d2, d1		; set d1 if we're on the top row
	btst	#ButtonDown, d1
	beq.s	loc_E0F2	; if we didn't press down or we are on the bottom, branch
	bset	#0, d6		; set bottom row
	bra.s	loc_E126
loc_E0F2:
	not.b	d2	; reverse bits so get the 3rd bit of the index
	move.b	d7, d1
	and.b	d2, d1
	btst	#ButtonLeft, d1
	beq.s	loc_E104	; if we didn't press left or we are on the left column, branch
	bclr	#1, d6		; set left column
	bra.s	loc_E126
loc_E104:
	add.b	d2, d2	; shift left by 1 (for right direction)
	not.b	d2		; reverse again
	move.b	d7, d1
	and.b	d2, d1
	btst	#ButtonRight, d1
	bne.s	loc_E122			; if we pressed right and we are on the left column, branch
loc_E112:
	addq.b	#1, $D(a6)
	andi.b	#3, $D(a6)
	beq.w	loc_D6B8
	rts
loc_E122:
	bset	#1, d6			; set right column
loc_E126:
	move.b	d6, $D(a6)
	bsr.w	loc_D6E2
	move.b	$D(a6), $C(a6)	; save index 
	clr.b	$D(a6)
	bra.w	loc_D6FC

