Battle_Escape:
	subq.b	#1, (battle_msg_timer).w
	beq.s	+			; if the timer for the message is 0, continue
	rts							; otherwise return and wait until it's 0
+
	bsr.w	GenerateRandomNumber
	move.b	$69(a6), d1		; is escape % 0?
	beq.s	loc_E8F6		; if so, branch -- failed to escape
	bclr	#7, $FFFFD009.w	; clear surprised enemy bit
	bne.s	Battle_Exit		; if it was set, branch -- we surprised the enemy, meaning we can always escape at the first turn
	add.b	$6A(a6), d1		; add escape % to power got from Rimit
	bcs.s	Battle_Exit		; if higher than 255, escape
	cmp.b	d1, d0			; compare escape rate to random number
	bcc.s	loc_E8F6		; if random number is bigger, we don't exit battle
Battle_Exit:
	st	(game_general_routine).w	; exit battle
	rts

