	lea	(loc_3D94E).l, a0	; load "can't get away" message
	lea	$FFFF2C0A, a1
	bra.w	loc_FF0A

Battle_EscapeFailedWait:
	subq.b	#1, (battle_msg_timer).w
	bne.s	loc_E922				; stay in this routine if timer is not 0
	addq.w	#4, (game_general_routine).w	; go to Battle_SetupAmbush
