	move.b	(joypad_pressed).w, d0
	andi.b	#Button_B_Mask|Button_C_Mask|Button_A_Mask, d0	; check for B, C or A press
	beq.s	+				; if none are pressed, return
	jsr	(GetSelectionSound).l		; otherwise stop displaying battle message
	move.w	$2(a6), (game_general_routine).w	; proceed to the routine we saved earlier
+
	rts

