Obj_Mieu:
	move.w	$2(a5), d0
	jmp	ObjMieu_Routines(pc,d0.w)
; ------------------------
ObjMieu_Routines:
	bra.w	ObjMieu_Init
	bra.w	ObjMieu_Main
	bra.w	ObjMieu_Done
; ------------------------
ObjMieu_Init:
	tst.w	(generation_index).w
	bne.s	ObjMieu_Clear			; if we're not in the 1st generation, branch
	tst.b	(event_flags+8).w	; did we talk to a guy who says he saw a Layan by the lake, etc... ?
	beq.s	ObjMieu_Clear			;  if not, branch - don't make Mieu appear
	tst.b	(event_flags+9).w	; do we have Mieu?
	beq.s	ObjMieu_Init_Part2	; if not, initialize sprite properties and events
ObjMieu_Clear:
	clr.w	(a5)
	rts

ObjMieu_Init_Part2:
	moveq	#0, d0
	move.l	#loc_1E028, $10(a5)
	move.w	#8, $18(a5)
	move.w	d0, $C(a5)
	move.w	d0, $22(a5)
	move.w	#$4000, $14(a5)
	st	$E(a5)
	move.w	#$A80, $8(a5)
	move.w	#$1F8, $A(a5)
	move.w	#loc_26804-GameScript, $26(a5)
	move.b	#1, $37(a5)
	addq.w	#4, $2(a5)	; ObjMieu_Main
	jsr	(SetSpriteVisibility).l
	jmp	(DisplaySprite).l

ObjMieu_Main:
	btst	#5, (a5)	; is Mieu visible?
	beq.s	+			; if so, continue
	jmp	(SetSpriteVisibility).l	; otherwise check visibility and return
+
	btst	#5, $FFFFD006.w
	beq.s	+
	moveq	#0, d1
	moveq	#0, d2
	jsr	(loc_6B0C).l
	beq.s	+
	bset	#1, $FFFFD006.w
	addq.w	#1, (party_members_num).w	; update number of party members
	addq.w	#4, $2(a5)	; ObjMieu_Done
+
	jsr	(SetSpriteVisibility).l
	jsr	(loc_67C6).l
	jmp	(DisplaySprite).l

ObjMieu_Done:
	btst	#1, $FFFFD006.w
	beq.s	+
	jsr	(SetSpriteVisibility).l	
	jsr	(loc_67C6).l	
	jmp	(DisplaySprite).l	
+
	st	(event_flags+9).w	; set 'Got Mieu' event
	clr.w	(a5)
	move.w	#$8F, d0
	jmp	(loc_147EE).l
	
