Obj_PrisonDoor:
	move.w	$2(a5), d0
	jmp	ObjPrisonDoor_Routines(pc,d0.w)

ObjPrisonDoor_Routines:
	bra.w	ObjPrisonDoor_Init		; 0
	bra.w	ObjPrisonDoor_Main		; 4
	bra.w	ObjPrisonDoor_Opening	; 8
	bra.w	ObjPrisonDoor_Open		; $C

ObjPrisonDoor_Init:
	moveq	#0, d0
	move.l	#loc_2141C, $10(a5)
	move.w	#4, $18(a5)
	move.w	d0, $C(a5)
	move.w	d0, $22(a5)
	move.w	#0, $14(a5)
	moveq	#0, d0
	move.b	$32(a5), d0		; get event_flags offset
	lea	(event_flags).w, a0
	tst.b	(a0,d0.w)	; did we already open the prison door?
	bne.s	MoveTo_PrsnDoorOpen	; if so, branch
	addq.w	#4, $2(a5)
	jsr	(SetSpriteVisibility).l
	jmp	(loc_5056).l

MoveTo_PrsnDoorOpen:
	move.w	#$C, $2(a5)
	subi.w	#$20, $A(a5)	; shift door up
	bra.w	ObjPrisonDoor_Open

ObjPrisonDoor_Main:
	move.w	$8(a5), d0	; get x position
	move.w	$A(a5), d1	; get y position
	move.w	d0, d2
	move.w	d0, d3
	addi.w	#$10, d1 	; increase y range by 16 (so that collision happens at the bottom)
	subq.w	#8, d2		; left x range
	addi.w	#9, d3		; right x range
loc_13070:
	move.w	(char_sprite_manager+8).w, d4	; get x position of main object (character sprites manager)
	sub.w	(char_sprite_manager+$A).w, d1	; subtract door y position plus range by the main object y position
	bne.s	+							; branch if difference is not 0
	sub.w	d4, d2						; subtract door x position with left range by the main object x position
	sub.w	d4, d3						; subtract door x position with right range by the main object x position
	eor.w	d2, d3						; check sign bit
	bpl.s	+							; if they are the same sign, then you are not in range, so don't do anything
	addq.w	#4, $2(a5)					; otherwise go to next routine
	clr.w	$30(a5)
+
	jsr	(SetSpriteVisibility).l
	jsr	(loc_67C6).l
	jmp	(DisplaySprite).l

ObjPrisonDoor_Opening:
	addq.b	#1, $C(a5)	; increment timer
	andi.b	#$F, $C(a5)	; iterate 16 times
	beq.s	loc_130CA	; if we processed this part 16 times, branch
	addq.w	#2, $30(a5)
	subq.w	#2, $A(a5)	; decrease y position by 2
	jsr	(SetSpriteVisibility).l
	move.w	$30(a5), d7
	add.w	d7, $1C(a5)
	jsr	(DisplaySprite).l
	sub.w	d7, $1C(a5)
	rts

