StopZ80:
	bset	#3, $FFFFD006.w		; set 'Z80 stopped' bit
-
	move.w	#$100, z80_bus_request	; stop Z80
	btst	#0, z80_bus_request		; has Z80 stopped?
	bne.s	-						; if not, loop until it has
	rts

StartZ80:
	move.w	#0, z80_bus_request	; Start Z80
	bclr	#3, $FFFFD006.w		; clear 'Z80 stopped' bit
	rts

ResumeOrStopMusic:
	bsr.s	StopZ80
-
	btst	#0, z80_bus_request ; again? Anyway, check if Z80 stopped
	bne.s	-
	move.b	d0, $00A01C10	; update value in Z80 RAM
	bsr.s	StartZ80
	rts
	

ClearZ80RAM:
	lea	z80_ram, a0
	move.w	#$1FFF, d0
	moveq	#0, d1
-
	move.b	d1, (a0)+
	dbf	d0, -
	rts

