	align 2
	
; Load new treasure chest after a particular event
Obj_EventTreasureChest:
	lea	(treasure_chest_flags).w, a0	; load the flags
	moveq	#0, d0
	move.b	$1(a5), d0	; get ID
	tst.b	(a0,d0.w)	; did we get past the event
	bne.s	loc_17F32	; is so, branch
	clr.w	(a5)		; otherwise clear
	rts
	
loc_17F32:
	addq.b	#1, $1(a5)	; get ID for the actual chest
	move.l	#Obj_TreasureChest, $4(a5)	; and save pointer
	
	
Obj_TreasureChest:
	move.w	$2(a5), d0
	jmp	ObjTreasureChest_Routines(pc,d0.w)

ObjTreasureChest_Routines:
	bra.w	ObjTreasureChest_Init
	bra.w	ObjTreasureChest_Main
	bra.w	ObjTreasureChest_Done

ObjTreasureChest_Init:
	moveq	#0, d0
	move.w	#4, $18(a5)
	move.w	d0, $C(a5)
	move.w	d0, $22(a5)
	move.w	#$4000, $14(a5)
	move.w	#loc_286B4-GameScript, $26(a5)
	move.b	$1(a5), d0	; get chest ID
	cmpi.b	#$58, d0	; is it the Miun Claw?
	beq.s	loc_17F82	; if yes, branch
	move.l	#loc_21404, $10(a5)
	bra.s	+

loc_17F82:
	move.l	#loc_21410, $10(a5)
+
	clr.b	$1(a5)
	move.b	d0, $32(a5)	; store chest ID
	add.w	d0, d0
	move.w	d0, d1
	add.w	d0, d0
	add.w	d1, d0		; multiply by 6
	lea	(TreasureChestData).l, a0
	adda.w	d0, a0		; get chest data indicated by ID
	move.w	(a0)+, $8(a5)	; store x position
	move.w	(a0)+, $A(a5)	; store y position
	move.w	(a0), $30(a5)	; store item ID
	move.w	#4, $2(a5)		; next routine
	lea	(treasure_chest_flags).w, a0 
	moveq	#0, d0
	move.b	$32(a5), d0	; get chest ID
	tst.b	(a0,d0.w)	; test if byte indicated by offset is set
	beq.s	loc_17FCE	; if it's not, display object and move to main routine
	move.w	#2, $22(a5)
	addq.w	#4, $2(a5)	; it's already open, so just display chest
loc_17FCE:
	jsr	(SetSpriteVisibility).l
	jsr	(loc_67C6).l
	jmp	(DisplaySprite).l

ObjTreasureChest_Main:
	btst	#5, (a5)
	beq.s	+
	jmp	(SetSpriteVisibility).l
+
	btst	#5, $FFFFD006.w
	beq.s	ObjTreasureChest_Done
	moveq	#0, d1
	moveq	#0, d2
	jsr	(loc_6AF2).l
	beq.s	ObjTreasureChest_Done
	bsr.w	Chest_PutInCharInventory
	bcs.s	ObjTreasureChest_Done
	moveq	#0, d0
	move.b	$32(a5), d0
	lea	(treasure_chest_flags).w, a0
	st	(a0,d0.w)
	addq.w	#2, $22(a5)
	addq.w	#4, $2(a5)
	move.w	#$B7, d2
	jsr	(loc_14836).l
ObjTreasureChest_Done:
	jsr	(SetSpriteVisibility).l
	jsr	(loc_67C6).l
	jmp	(DisplaySprite).l

Chest_PutInCharInventory:
	bclr	#5, $FFFFD006.w
	lea	(char_inventory).w, a0
	move.w	(party_members_num).w, d1
	moveq	#0, d2
loc_18048:
	cmpi.w	#$1E, (a0)
	bcs.s	loc_18064
	lea	$20(a0), a0
	addq.w	#1, d2
	dbf	d1, loc_18048
	move.w	#loc_286CE-GameScript, (script_offset).w
	move	#1, ccr
	rts
loc_18064:
	move.l	#$FFFFC0A7, d1
	lsl.w	#7, d2
	add.w	d2, d1
	move.l	d1, (char_name_saved).w
	moveq	#0, d0
	move.w	$30(a5), d0
	bmi.s	loc_180A0
	addq.w	#2, (a0)
	adda.w	(a0), a0
	move.w	d0, (a0)
	lea	(InventoryData).l, a0
	adda.w	d0, a0
	move.w	$2(a0), d0
	move.l	#InventoryNameData, d1
	add.l	d0, d1
	move.l	d1, $FFFFD484.w
	move.w	#loc_286B4-GameScript, (script_offset).w
	rts
loc_180A0:
	andi.l	#$7FFF, d0
	add.l	d0, (money_owned).w
	move.l	d0, $FFFFD4A0.w
	move.w	#loc_28702-GameScript, (script_offset).w
	rts
	
; =======================================
; bytes 1-2 = X position
; bytes 3-4 = Y position
; bytes 5-6 = offset for InventoryData item (if MSB is set, the content is money)
;
; There is some data with all bytes set to 0. That's for the chests which appear only after certain events.
; For example, the chest with the Sapphire appears after talking to Lyle, so the data before the Sapphire have bytes set to 0
; =======================================
TreasureChestData:
	dc.w	$0270, $0150, ItemID_Knife		; 0
	dc.w	$0370, $0150, ItemID_Monitor	; 1
	dc.w	0, 0, 0							; 2
	dc.w	$0170, $D8, ItemID_Sapphire		; 3
	dc.w	$0620, $0360, ItemID_Trimate	; 4
	dc.w	$03B0, $D0, ItemID_Dimate		; 5
	dc.w	$01D0, $0290, ItemID_Dimate		; 6
	dc.w	$0490, $0360, ItemID_Antidote	; 7
	dc.w	$0430, $0100, ItemID_Monomate	; 8
	dc.w	$0300, $0158, ItemID_Dimate		; 9
	dc.w	$02F0, $0320, ItemID_Antidote	; $A
	dc.w	$0490, $0338, ItemID_Escapipe	; $B
	dc.w	$03F0, $02E0, ItemID_Shield		; $C
	dc.w	$05B0, $0120, ItemID_Antidote	; $D
	dc.w	$05B0, $0320, ItemID_Monomate	; $E
	dc.w	$01D0, $01A0, ItemID_Antidote	; $F
	dc.w	$02D0, $02A0, ItemID_Dimate		; $10
	dc.w	$05B0, $0320, ItemID_Dimate		; $11
	dc.w	$B0, $0220, ItemID_Dimate		; $12
	dc.w	$01F0, $01F0, ItemID_Escapipe	; $13
