SoundDriver:

	org 0
	save
	include	"sound/ps3.sounddriver.asm"
	restore
	padding off
	org (SoundDriver+SoundDriver_End-SoundDriver_Start)
	
; -------------------------------------------------------------------------
	
SFXPointerTable:

; SFX pointers are stored in Z80 RAM starting from address $1000.
	org $1000
	save
	include	"sound/ps3.sfx.asm"
	restore
	padding off
	org (SFXPointerTable+AllSFXPtrTableZ80_End-SFXPtrTableZ80)
	
	if (*) > RomSoundBank+$8000
	warning "Sound bank size is higher than $8000 bytes"
	endif
	
